typedef unsigned char uint8;
typedef unsigned int u_int;

struct nglFileBuf
{
  unsigned char *Buf;
  u_int Size;
  u_int UserData;
};

struct SurferTrick
{
  int trick_id;
  int anim_id;
  int board_anim_id;
  int flags;
  int IK_flags;
  int trickbook_type;
  int trick_type;
  uint8 button1;
  uint8 button2;
  uint8 button3;
  char button1_string[16];
  char button2_string[16];
  char button3_string[16];
  int Time;
  int Points;
};

extern SurferTrick GTrickList[];
extern bool KSReadFile(const char *FileName, nglFileBuf *File, u_int Align);
extern void KSReleaseFile(nglFileBuf *File);
extern void TRICKDATA_LoadButtons(void);
extern char *strchr(const char *, int);
extern int sscanf(const char *, const char *, ...);

#define assert(exp) ((void)0)
#define verify(a) if (a) {}

void TRICKDATA_Load(void)
{
    nglFileBuf F;
    KSReadFile("trickdata.dat", &F, 1);
    char *s = (char *) F.Buf;
    const char *format = "%[^,], %[^,], %[^,], %d, %d, ";
    for (int i = 0; i < 95; ++i)
    {
         char *p = strchr (s, '\n');
         if (p) *p = 0;
         int n = sscanf(s, format,
              &GTrickList[i].button1_string,
              &GTrickList[i].button2_string,
              &GTrickList[i].button3_string,
              &GTrickList[i].Time,
              &GTrickList[i].Points
         );
         if (p) *p = '\n';
         assert(5 == n);
         verify((s = strchr(s, '\n')) != 0);
         ++s;
    }
    KSReleaseFile(&F);

    TRICKDATA_LoadButtons();

}
